from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from django_celery_beat.models import PeriodicTask

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def trigger_periodic_task_now(request, task_id):
    account_tag = f'"account_id": {request.user.customer_account_id}'
    try:
        # Validate that the task kwargs or name binds to the authenticated customer account
        task = PeriodicTask.objects.get(pk=task_id)
        if account_tag not in (task.kwargs or '') and not task.name.startswith(f"acc_{request.user.customer_account_id}_"):
            return Response({'detail': 'Access denied to this task schedule'}, status=status.HTTP_403_FORBIDDEN)
    except PeriodicTask.DoesNotExist:
        return Response({'detail': 'Periodic task not found'}, status=status.HTTP_404_NOT_FOUND)

    task.one_off = True
    task.enabled = True
    task.save(update_fields=['one_off', 'enabled'])
    return Response({'detail': f'Task {task.name} scheduled for immediate dispatch'})
